{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2176-07-13 14:12:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee, one of the neurosurgery team. You're in the hospital after being found unconscious outside a building. You had a fall and hit your head."
    },
    {
      "turn_number": 2,
      "time": "2176-07-13 14:13:00",
      "speaker": "Patient",
      "text": "I... I don’t remember anything. My head hurts."
    },
    {
      "turn_number": 3,
      "time": "2176-07-13 14:14:00",
      "speaker": "Doctor",
      "text": "You have a head injury. The scan shows bleeding in your brain on the left side, called a subarachnoid hemorrhage. There’s also a skull fracture behind your left ear."
    },
    {
      "turn_number": 4,
      "time": "2176-07-13 14:15:00",
      "speaker": "Patient",
      "text": "Is it serious?"
    },
    {
      "turn_number": 5,
      "time": "2176-07-13 14:16:00",
      "speaker": "Doctor",
      "text": "Yes, it is. Later that evening, another scan showed the bleeding got worse. There’s now a large clot in the brain with swelling pushing the brain to the right side."
    },
    {
      "turn_number": 6,
      "time": "2176-07-13 14:17:00",
      "speaker": "Patient",
      "text": "Will I need surgery?"
    },
    {
      "turn_number": 7,
      "time": "2176-07-13 14:18:00",
      "speaker": "Doctor",
      "text": "We reviewed your case carefully. Because of your other health issues—like heart failure and lung disease—the risk of surgery is too high. We’re focusing on comfort and managing the pressure in your brain."
    },
    {
      "turn_number": 8,
      "time": "2176-07-13 14:19:00",
      "speaker": "Patient",
      "text": "I see..."
    },
    {
      "turn_number": 9,
      "time": "2176-07-14 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re still on the ventilator because you’re not breathing well on your own. We’re also watching your blood pressure and kidney function closely."
    },
    {
      "turn_number": 10,
      "time": "2176-07-14 08:01:00",
      "speaker": "Patient",
      "text": "My chest feels heavy."
    },
    {
      "turn_number": 11,
      "time": "2176-07-14 08:02:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray shows some fluid in the lungs, likely from heart failure. We’re giving diuretics to help reduce the fluid."
    },
    {
      "turn_number": 12,
      "time": "2176-07-14 08:03:00",
      "speaker": "Patient",
      "text": "Okay."
    },
    {
      "turn_number": 13,
      "time": "2176-07-15 09:00:00",
      "speaker": "Doctor",
      "text": "We started you on insulin because your blood sugar was high. Your heart function is very weak—your ejection fraction is only 10%. We’re adjusting your medications carefully."
    },
    {
      "turn_number": 14,
      "time": "2176-07-15 09:01:00",
      "speaker": "Patient",
      "text": "I’ve had heart problems for years."
    },
    {
      "turn_number": 15,
      "time": "2176-07-15 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, and we’re managing that. But right now, the brain injury is the main concern. Your family was contacted and they’re trying to understand the situation."
    },
    {
      "turn_number": 16,
      "time": "2176-07-16 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve developed a fever. We took cultures and started antibiotics for pneumonia. The sputum grew Enterobacter, which is sensitive to the antibiotics you’re on."
    },
    {
      "turn_number": 17,
      "time": "2176-07-16 10:01:00",
      "speaker": "Patient",
      "text": "I feel hot."
    },
    {
      "turn_number": 18,
      "time": "2176-07-16 10:02:00",
      "speaker": "Doctor",
      "text": "We’re treating the infection. Your white blood cell count is high, which confirms your body is fighting something."
    },
    {
      "turn_number": 19,
      "time": "2176-07-17 08:00:00",
      "speaker": "Doctor",
      "text": "Your sodium level is rising. It’s now 150. We’re giving free water flushes to bring it down slowly."
    },
    {
      "turn_number": 20,
      "time": "2176-07-17 08:01:00",
      "speaker": "Patient",
      "text": "I’m thirsty."
    },
    {
      "turn_number": 21,
      "time": "2176-07-17 08:02:00",
      "speaker": "Doctor",
      "text": "I know, but we have to be careful. Too much fluid too fast could worsen brain swelling. We’re monitoring closely."
    },
    {
      "turn_number": 22,
      "time": "2176-07-18 09:00:00",
      "speaker": "Doctor",
      "text": "The chest X-ray shows the pneumonia is getting worse. We’re continuing the same antibiotics. The nodules we saw might be from infection or fluid, but we’re watching."
    },
    {
      "turn_number": 23,
      "time": "2176-07-18 09:01:00",
      "speaker": "Patient",
      "text": "Is it spreading?"
    },
    {
      "turn_number": 24,
      "time": "2176-07-18 09:02:00",
      "speaker": "Doctor",
      "text": "The infection is in your lungs, but we’re treating it. Your body is weak from the brain injury, so it’s harder to fight."
    },
    {
      "turn_number": 25,
      "time": "2176-07-19 07:00:00",
      "speaker": "Doctor",
      "text": "Your neurological exam hasn’t improved. You’re not moving your right side, which suggests a stroke-like effect from the brain bleed."
    },
    {
      "turn_number": 26,
      "time": "2176-07-19 07:01:00",
      "speaker": "Patient",
      "text": "I can’t feel my right arm."
    },
    {
      "turn_number": 27,
      "time": "2176-07-19 07:02:00",
      "speaker": "Doctor",
      "text": "That’s due to the injury on the left side of your brain. Unfortunately, with the extent of the damage, recovery is unlikely."
    },
    {
      "turn_number": 28,
      "time": "2176-07-20 10:00:00",
      "speaker": "Doctor",
      "text": "We did another brain scan. The bleeding in the left side has slightly decreased, but the clot in the right frontal lobe has grown. The pressure in your brain is still high."
    },
    {
      "turn_number": 29,
      "time": "2176-07-20 10:01:00",
      "speaker": "Patient",
      "text": "So it’s getting worse?"
    },
    {
      "turn_number": 30,
      "time": "2176-07-20 10:02:00",
      "speaker": "Doctor",
      "text": "The overall situation remains very serious. The new bleeding adds to the damage. We’re focusing on keeping you comfortable."
    },
    {
      "turn_number": 31,
      "time": "2176-07-21 11:00:00",
      "speaker": "Doctor",
      "text": "Your family met with us yesterday. They understand your condition is not improving. They’re discussing what to do next."
    },
    {
      "turn_number": 32,
      "time": "2176-07-21 11:01:00",
      "speaker": "Patient",
      "text": "I want to go home."
    },
    {
      "turn_number": 33,
      "time": "2176-07-21 11:02:00",
      "speaker": "Doctor",
      "text": "I understand. But right now, you need the ventilator to breathe. Your body isn’t strong enough to do it on its own."
    },
    {
      "turn_number": 34,
      "time": "2176-07-22 08:00:00",
      "speaker": "Doctor",
      "text": "Your kidney function is declining. BUN is 94, creatinine 1.5. We’re not giving certain medications to avoid further strain."
    },
    {
      "turn_number": 35,
      "time": "2176-07-22 08:01:00",
      "speaker": "Patient",
      "text": "My legs are swollen."
    },
    {
      "turn_number": 36,
      "time": "2176-07-22 08:02:00",
      "speaker": "Doctor",
      "text": "That’s from fluid buildup due to heart and kidney issues. We’re balancing fluids carefully."
    },
    {
      "turn_number": 37,
      "time": "2176-07-23 09:00:00",
      "speaker": "Doctor",
      "text": "You’re having trouble maintaining blood pressure. We started Levophed to support it. Your body is under a lot of stress."
    },
    {
      "turn_number": 38,
      "time": "2176-07-23 09:01:00",
      "speaker": "Patient",
      "text": "I feel weak."
    },
    {
      "turn_number": 39,
      "time": "2176-07-23 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, and your exam shows no response to pain. The brain injury is severe. We’ve made you DNR/DNI for now, pending your family’s final decision."
    },
    {
      "turn_number": 40,
      "time": "2176-07-23 14:00:00",
      "speaker": "Doctor",
      "text": "Your family arrived. After discussion, they’ve decided to make you comfort measures only. We’ll stop the ventilator and keep you comfortable."
    },
    {
      "turn_number": 41,
      "time": "2176-07-23 14:01:00",
      "speaker": "Patient",
      "text": "Thank you for taking care of me."
    },
    {
      "turn_number": 42,
      "time": "2176-07-24 15:00:00",
      "speaker": "Doctor",
      "text": "The family is here with you. We’re going to remove the breathing tube now. You’re not alone."
    },
    {
      "turn_number": 43,
      "time": "2176-07-24 15:08:00",
      "speaker": "Doctor",
      "text": "We are now terminating mechanical ventilation."
    },
    {
      "turn_number": 44,
      "time": "2176-07-24 15:40:00",
      "speaker": "Doctor",
      "text": "Time of death is 15:44."
    }
  ],
  "summary": {
    "admission_start": "2176-07-13 14:12:00",
    "admission_end": "2176-07-24 15:40:00",
    "summary_paragraph": "A man with a complex medical history including non-ischemic cardiomyopathy, COPD, insulin-dependent diabetes, and polysubstance use was admitted after being found unconscious following a fall. Initial imaging revealed a left subarachnoid hemorrhage and a skull fracture. His condition declined rapidly with a large intraparenchymal hemorrhage and 11 mm midline shift, leading to a decision against surgical intervention due to poor prognosis. He remained intubated and developed complications including pneumonia, acute kidney injury, hypernatremia, and hypotension. Despite supportive care, there was no neurological improvement. After a family meeting, the decision was made to transition to comfort measures only. He was terminally extubated and passed away on the final day of admission.",
    "problems": [
      "Traumatic subarachnoid hemorrhage without loss of consciousness, initial encounter",
      "Pneumonia, unspecified organism",
      "Acute respiratory failure with hypoxia",
      "Acute kidney failure, unspecified",
      "Hyperosmolality and hypernatremia",
      "Other hypotension",
      "Chronic obstructive pulmonary disease, unspecified",
      "Other cardiomyopathies",
      "Hemiplegia, unspecified affecting right dominant side",
      "Other fracture of base of skull, initial encounter",
      "Type 2 diabetes mellitus without complications",
      "Long term (current) use of insulin",
      "Unspecified viral hepatitis C without hepatic coma",
      "Schizophrenia, unspecified",
      "Cocaine abuse, uncomplicated",
      "Alcohol abuse, uncomplicated",
      "Nicotine dependence, cigarettes, uncomplicated",
      "Cannabis abuse, uncomplicated",
      "Hypertensive chronic kidney disease with stage 1 through stage 4 chronic kidney disease, or unspecified chronic kidney disease",
      "Chronic kidney disease, unspecified",
      "Solitary pulmonary nodule",
      "Do not resuscitate"
    ]
  }
}
